import React, { useEffect, useRef, useState } from 'react';
import {
  Image, ImageBackground, KeyboardAvoidingView, Modal, Platform, Pressable,
  ScrollView, StyleSheet, Text, TextInput, View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useVideoPlayer, VideoView } from 'expo-video';
import { AgoraVideoTile, agoraUidFor } from '../lib/streaming';
import { ActionButton, Avatar, CircleTile, EmptyState, Pill, PostCard, SectionTitle, TopBar, formatCount } from '../components/Primitives';
import { colors } from '../theme';
import { styles } from '../appStyles';
import type { Circle, CircleJoinRequest, CirclePost, Conversation, DirectMessage, Gift, LiveGiftEvent, LiveSession, PostComment, Profile, UUID } from '../types';

export type Tab = 'home' | 'circles' | 'live' | 'inbox' | 'profile';
export type Attachment = { uri: string; mimeType: string; fileName: string; kind: 'image' | 'gif' | 'video' };

export function HomeScreen({ profile, circles, lives, feed, feedHasMore, feedLoadingMore, onLoadMore, onProfile, onLive, onLiveList, onCreatePost, onExplore, onLike, onReply, onReport, onCircle }: { profile: Profile; circles: Circle[]; lives: LiveSession[]; feed: CirclePost[]; feedHasMore: boolean; feedLoadingMore: boolean; onLoadMore: () => void; onProfile: () => void; onLive: (session: LiveSession) => void; onLiveList: () => void; onCreatePost: () => void; onExplore: () => void; onLike: (id: UUID) => void; onReply: (post: CirclePost) => void; onReport: (kind: 'post' | 'profile' | 'circle' | 'message' | 'live_session', id: UUID, user?: UUID) => void; onCircle: (circle: Circle) => void }) {
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
  const today = new Date().toLocaleDateString('en-GB', { weekday: 'long', month: 'long', day: 'numeric' }).toUpperCase();
  return <ScrollView ref={undefined} contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}>
    <TopBar profile={profile} onProfile={onProfile} />
    <View style={styles.greeting}><Text style={styles.greetingEyebrow}>{today}</Text><Text style={styles.greetingTitle}>A place to find{ '\n' }your people.</Text><Text style={styles.greetingCopy}>{greeting}, {profile.displayName.split(' ')[0]}. What feels like you today?</Text></View>
    <View style={styles.quickActions}><Pressable style={styles.quickAction} onPress={onCreatePost}><Text style={styles.quickEmoji}>✎</Text><Text style={styles.quickText}>Share a thought</Text></Pressable><Pressable style={[styles.quickAction, styles.quickActionTint]} onPress={() => lives[0] ? onLive(lives[0]) : onExplore()}><Text style={styles.quickEmoji}>◉</Text><Text style={styles.quickText}>{lives.length ? 'Join something live' : 'Explore circles'}</Text></Pressable></View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="HAPPENING NOW" title="Live in your circles" action="See all" onAction={onLiveList} />
      {lives.slice(0, 2).map((session, index) => <Pressable key={session.id} onPress={() => onLive(session)} style={[styles.liveFeature, index === 1 && { backgroundColor: colors.night }]}>
        <ImageBackground source={{ uri: index === 0 ? 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=900&h=600&fit=crop' : 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?w=900&h=600&fit=crop' }} style={styles.liveFeatureImage} imageStyle={{ borderRadius: 23 }}>
          <View style={styles.liveShade} /><View style={styles.liveTop}><View style={styles.liveBadge}><View style={styles.liveDot} /><Text style={styles.liveBadgeText}>LIVE</Text></View><Text style={styles.viewerChip}>◉ {formatCount(session.viewerCount)}</Text></View>
          <View style={styles.liveBottom}><View style={styles.liveHost}><Avatar profile={session.host} size={35} ring /><View><Text style={styles.liveHostName}>{session.host.displayName}</Text><Text style={styles.liveCircleName}>{session.circleName}</Text></View></View><View style={styles.playButton}><Text style={styles.playText}>▶</Text></View></View>
          <Text numberOfLines={1} style={styles.liveFeatureTitle}>{session.title}</Text>
        </ImageBackground>
      </Pressable>)}
    </View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR LITTLE CORNERS" title="Your circles" action="Explore" onAction={onExplore} /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ paddingRight: 22 }}>{circles.filter((circle) => circle.isMember).map((circle) => <Pressable key={circle.id} onPress={() => onCircle(circle)} style={[styles.miniCircle, { backgroundColor: circle.color }]}><Text style={styles.miniCircleEmoji}>{circle.interest === 'Film' ? '🎞️' : circle.interest === 'Gardening' ? '🌱' : circle.interest === 'Music' ? '🎧' : '🫶'}</Text><Text numberOfLines={2} style={styles.miniCircleName}>{circle.name}</Text><Text style={styles.miniCircleCount}>{formatCount(circle.members)} members</Text></Pressable>)}</ScrollView></View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="FROM YOUR PEOPLE" title="The latest" action="Write a post" onAction={onCreatePost} />{feed.map((post) => <PostCard key={post.id} post={post} onLike={() => onLike(post.id)} onReply={() => onReply(post)} onOpenCircle={() => { const circle = circles.find((item) => item.id === post.circleId); if (circle) onCircle(circle); }} onMore={() => onReport('post', post.id, post.author.id)} />)}{feedHasMore ? <ActionButton compact variant="outline" label={feedLoadingMore ? 'Loading posts…' : 'Load more posts'} disabled={feedLoadingMore} onPress={onLoadMore} /> : null}</View>
  </ScrollView>;
}

export function ExploreScreen({ profile, people: suggestedPeople, followingIds, onFollow, onOpenProfile, peopleHasMore, peopleLoadingMore, onLoadMorePeople, circles, joiningCircleIds, circlesHasMore, circlesLoadingMore, onLoadMoreCircles, requested, requests, searchText, onSearch, filter, onFilter, onJoin, onCreate, onProfile, onReport, onCircle, onRequestDecision }: { profile: Profile; people: Profile[]; followingIds: Set<UUID>; onFollow: (person: Profile) => void; onOpenProfile: (person: Profile) => void; peopleHasMore: boolean; peopleLoadingMore: boolean; onLoadMorePeople: () => void; circles: Circle[]; joiningCircleIds: Set<UUID>; circlesHasMore: boolean; circlesLoadingMore: boolean; onLoadMoreCircles: () => void; requested: Set<UUID>; requests: CircleJoinRequest[]; searchText: string; onSearch: (text: string) => void; filter: string; onFilter: (filter: string) => void; onJoin: (circle: Circle) => void; onCreate: () => void; onProfile: () => void; onReport: (type: 'circle', id: UUID) => void; onCircle: (circle: Circle) => void; onRequestDecision: (request: CircleJoinRequest, accepted: boolean) => void }) {
  const interests = ['For you', 'Film', 'Gardening', 'Art', 'Cooking', 'Music', 'Slow living'];
  const rankedPeople = [...suggestedPeople].sort((a, b) => {
    const myInterests = new Set(profile.interests.map((interest) => interest.toLowerCase()));
    const shared = (person: Profile) => person.interests.filter((interest) => myInterests.has(interest.toLowerCase())).length;
    return shared(b) - shared(a);
  });
  return <ScrollView contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}><TopBar profile={profile} onProfile={onProfile} />
    <View style={styles.screenHeading}><Text style={styles.screenEyebrow}>FIND YOUR PEOPLE</Text><Text style={styles.screenTitle}>There’s a circle{ '\n' }for that.</Text><Text style={styles.screenCopy}>Find a small corner of the internet that feels like yours.</Text></View>
    <View style={styles.searchBox}><Text style={styles.searchIcon}>⌕</Text><TextInput value={searchText} onChangeText={onSearch} placeholder="Try film, baking, houseplants…" placeholderTextColor="#A6A0A0" style={styles.searchInput} /></View>
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.filterRow}>{interests.map((item) => <Pill key={item} label={item} selected={filter === item} onPress={() => onFilter(item)} />)}</ScrollView>
    <View style={styles.sectionPad}><SectionTitle eyebrow="PEOPLE TO MEET" title="Follow your curiosity" />{rankedPeople.map((person) => <View key={person.id} style={styles.conversationRow}><Pressable onPress={() => onOpenProfile(person)} accessibilityRole="button" accessibilityLabel={`Open ${person.displayName}'s profile`} style={styles.publicProfileRow}><Avatar profile={person} size={46} /><View style={styles.conversationMain}><Text style={styles.conversationName}>{person.displayName}</Text><Text numberOfLines={1} style={styles.conversationPreview}>@{person.handle} · {person.interests.slice(0, 2).join(' · ') || 'Circles member'}</Text></View></Pressable><Pressable onPress={() => onFollow(person)} accessibilityRole="button" accessibilityLabel={`${followingIds.has(person.id) ? 'Unfollow' : 'Follow'} ${person.displayName}`} style={[styles.followButton, followingIds.has(person.id) && styles.followingButton]}><Text style={[styles.followButtonText, followingIds.has(person.id) && styles.followingButtonText]}>{followingIds.has(person.id) ? 'Following' : 'Follow'}</Text></Pressable></View>)}{suggestedPeople.length === 0 ? <EmptyState emoji="🫶" title="Your people are on their way" detail="Sign in to discover members and follow each other." /> : null}{peopleHasMore ? <ActionButton compact variant="outline" label={peopleLoadingMore ? 'Loading people…' : 'Load more people'} disabled={peopleLoadingMore} onPress={onLoadMorePeople} /> : null}</View>
    <View style={styles.discoverBanner}><View style={{ flex: 1 }}><Text style={styles.discoverEyebrow}>MADE BY YOU</Text><Text style={styles.discoverTitle}>Your interests deserve a home.</Text><Text style={styles.discoverCopy}>Start a circle and invite the people who get it.</Text></View><Pressable onPress={onCreate} style={styles.discoverPlus}><Text style={styles.discoverPlusText}>＋</Text></Pressable></View>
    {requests.length ? <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR CIRCLES" title="Join requests" />{requests.map((request) => <View key={request.id} style={styles.membershipRequest}><Avatar profile={request.requester} size={39} /><View style={{ flex: 1 }}><Text style={styles.requestTitle}>{request.requester.displayName}</Text><Text style={styles.requestCopy}>Wants to join {request.circleName}</Text></View><Pressable onPress={() => onRequestDecision(request, false)} style={styles.requestDecline}><Text style={styles.requestDeclineText}>×</Text></Pressable><Pressable onPress={() => onRequestDecision(request, true)} style={styles.requestAccept}><Text style={styles.requestAcceptText}>Let in</Text></Pressable></View>)}</View> : null}
    <View style={styles.sectionPad}><SectionTitle eyebrow="A FEW GOOD PLACES" title={`${circles.length}${circlesHasMore ? '+' : ''} circles to explore`} />{circles.map((circle) => <CircleTile key={circle.id} circle={circle} requested={requested.has(circle.id)} joining={joiningCircleIds.has(circle.id)} onPress={() => onCircle(circle)} onJoin={() => onJoin(circle)} onMore={() => onReport('circle', circle.id)} />)}{circles.length === 0 ? <EmptyState emoji="🪴" title="No circles found" detail="Try another interest or search for something else." /> : null}{circlesHasMore ? <ActionButton compact variant="outline" label={circlesLoadingMore ? 'Loading circles…' : 'Load more circles'} disabled={circlesLoadingMore} onPress={onLoadMoreCircles} /> : null}</View>
  </ScrollView>;
}

export function LiveScreen({ profile, lives, onProfile, onLive, onStart }: { profile: Profile; lives: LiveSession[]; onProfile: () => void; onLive: (session: LiveSession) => void; onStart: () => void }) {
  return <ScrollView contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}><TopBar profile={profile} onProfile={onProfile} />
    <View style={styles.screenHeading}><Text style={styles.screenEyebrow}>A LITTLE LIVE MAGIC</Text><Text style={styles.screenTitle}>Come hang{ '\n' }for a while.</Text><Text style={styles.screenCopy}>Drop into a live room, say hello, and share the moment.</Text></View>
    <View style={styles.goLiveCard}><View style={styles.goLiveOrb}><Text style={styles.goLiveOrbText}>◉</Text></View><View style={{ flex: 1 }}><Text style={styles.goLiveTitle}>Your turn to host?</Text><Text style={styles.goLiveCopy}>Invite up to three people onto the stage.</Text></View><ActionButton compact label="Go live" onPress={onStart} /></View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="RIGHT NOW" title={`${lives.length} rooms are live`} />{lives.map((session, index) => <Pressable key={session.id} onPress={() => onLive(session)} style={styles.liveListCard}><ImageBackground source={{ uri: ['https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=900&h=600&fit=crop', 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?w=900&h=600&fit=crop', 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=900&h=600&fit=crop'][index % 3] }} style={styles.liveListImage} imageStyle={{ borderRadius: 22 }}><View style={styles.liveShade} /><View style={styles.liveTop}><View style={styles.liveBadge}><View style={styles.liveDot} /><Text style={styles.liveBadgeText}>LIVE</Text></View><Text style={styles.viewerChip}>◉ {formatCount(session.viewerCount)} watching</Text></View><View style={styles.liveListBottom}><View style={{ flex: 1 }}><Text style={styles.liveListCircle}>{session.circleName ?? 'Around Circles'}</Text><Text numberOfLines={2} style={styles.liveListTitle}>{session.title}</Text><View style={styles.liveListHost}><Avatar profile={session.host} size={26} /><Text style={styles.liveListName}>{session.host.displayName}</Text></View></View><View style={styles.playButton}><Text style={styles.playText}>▶</Text></View></View></ImageBackground></Pressable>)}</View>
  </ScrollView>;
}

export function InboxScreen({ profile, conversations, onProfile, onConversation }: { profile: Profile; conversations: Conversation[]; onProfile: () => void; onConversation: (conversation: Conversation) => void }) {
  return <ScrollView contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}><TopBar profile={profile} onProfile={onProfile} /><View style={styles.screenHeading}><Text style={styles.screenEyebrow}>ONE TO ONE</Text><Text style={styles.screenTitle}>Messages</Text><Text style={styles.screenCopy}>Good conversations start with a follow both ways.</Text></View>
    <View style={styles.messageBanner}><Text style={styles.messageBannerEmoji}>💌</Text><Text style={styles.messageBannerCopy}>Your inbox is for the people who follow you back.</Text></View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR PEOPLE" title="Recent chats" />{conversations.map((conversation) => <Pressable key={conversation.id} onPress={() => onConversation(conversation)} style={styles.conversationRow}><Avatar profile={conversation.peer} size={52} /><View style={styles.conversationMain}><View style={styles.conversationHead}><Text style={styles.conversationName}>{conversation.peer.displayName}</Text><Text style={styles.conversationTime}>{conversation.messages.at(-1)?.createdAt ?? ''}</Text></View><Text numberOfLines={1} style={styles.conversationPreview}>{conversation.messages.at(-1)?.body ?? 'Say hello 👋'}</Text></View>{conversation.unread > 0 ? <View style={styles.unreadDot}><Text style={styles.unreadText}>{conversation.unread}</Text></View> : null}</Pressable>)}{conversations.length === 0 ? <EmptyState emoji="🌱" title="A little quiet in here" detail="When you and someone else follow each other, your chat will show up here." /> : null}</View>
  </ScrollView>;
}

export function ProfileScreen({ profile, circles, followers, following, walletBalance, followingCount, followerCount, signedIn, backendReady: configured, authEmail, authPassword, authError, authBusy, profileSaving, onSaveProfile, onEmail, onPassword, onAuth, onStore, onCircle, onBlockFollower, onOpenProfile, onSignOut }: { profile: Profile; circles: Circle[]; followers: Profile[]; following: Profile[]; walletBalance: number; followingCount: number; followerCount: number; signedIn: boolean; backendReady: boolean; authEmail: string; authPassword: string; authError: string; authBusy: boolean; profileSaving: boolean; onSaveProfile: (input: Pick<Profile, 'displayName' | 'bio' | 'interests'>) => Promise<void>; onEmail: (text: string) => void; onPassword: (text: string) => void; onAuth: (kind: 'signIn' | 'signUp') => void; onStore: () => void; onCircle: (circle: Circle) => void; onBlockFollower: (profile: Profile) => void; onOpenProfile: (profile: Profile) => void; onSignOut: () => void }) {
  const [editing, setEditing] = useState(false);
  const [displayName, setDisplayName] = useState(profile.displayName);
  const [bio, setBio] = useState(profile.bio);
  const [interests, setInterests] = useState(profile.interests.join(', '));
  useEffect(() => { if (!editing) { setDisplayName(profile.displayName); setBio(profile.bio); setInterests(profile.interests.join(', ')); } }, [profile.displayName, profile.bio, profile.interests, editing]);
  return <ScrollView contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}><TopBar profile={profile} /><View style={styles.profileHero}><Avatar profile={profile} size={88} ring />{editing ? <><TextInput value={displayName} onChangeText={setDisplayName} placeholder="Display name" maxLength={60} style={styles.field} accessibilityLabel="Display name" /><Text style={styles.profileHandle}>@{profile.handle}</Text><TextInput value={bio} onChangeText={setBio} placeholder="A little about you" maxLength={300} multiline style={styles.field} accessibilityLabel="Profile bio" /><TextInput value={interests} onChangeText={setInterests} placeholder="Interests, separated by commas" maxLength={300} style={styles.field} accessibilityLabel="Your interests" /><ActionButton compact label={profileSaving ? 'Saving…' : 'Save profile'} disabled={profileSaving || displayName.trim().length < 2} onPress={() => void onSaveProfile({ displayName, bio, interests: [...new Set(interests.split(',').map((item) => item.trim()).filter(Boolean))] }).then(() => setEditing(false)).catch(() => {})} /><Pressable disabled={profileSaving} onPress={() => setEditing(false)} style={styles.profileEditCancel}><Text style={styles.signInText}>Cancel</Text></Pressable></> : <><Text style={styles.profileName}>{profile.displayName}</Text><Text style={styles.profileHandle}>@{profile.handle}</Text><Text style={styles.profileBio}>{profile.bio || 'Finding new corners of the internet.'}</Text>{signedIn ? <Pressable accessibilityRole="button" onPress={() => setEditing(true)} style={styles.profileEditButton}><Text style={styles.profileEditText}>Edit profile</Text></Pressable> : null}</>}<View style={styles.profileStats}><View style={styles.stat}><Text style={styles.statValue}>{circles.length}</Text><Text style={styles.statLabel}>circles</Text></View><View style={styles.statLine} /><View style={styles.stat}><Text style={styles.statValue}>{followingCount.toLocaleString()}</Text><Text style={styles.statLabel}>following</Text></View><View style={styles.statLine} /><View style={styles.stat}><Text style={styles.statValue}>{followerCount.toLocaleString()}</Text><Text style={styles.statLabel}>followers</Text></View></View></View>
    {signedIn ? <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR COMMUNITY" title="Followers" />{followers.map((follower) => <View key={follower.id} style={styles.followerRow}><Pressable onPress={() => onOpenProfile(follower)} accessibilityRole="button" accessibilityLabel={`Open ${follower.displayName}'s profile`} style={styles.publicProfileRow}><Avatar profile={follower} size={42} /><View style={styles.followerInfo}><Text numberOfLines={1} style={styles.followerName}>{follower.displayName}</Text><Text numberOfLines={1} style={styles.followerHandle}>@{follower.handle}</Text></View></Pressable><Pressable onPress={() => onBlockFollower(follower)} accessibilityRole="button" accessibilityLabel={`Block follower ${follower.displayName}`} style={styles.blockFollowerButton}><Text style={styles.blockFollowerText}>Block</Text></Pressable></View>)}{followers.length === 0 ? <EmptyState emoji="👋" title="No followers yet" detail="When someone follows you, you can manage them here." /> : null}</View> : null}
    {signedIn ? <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR COMMUNITY" title="Following" />{following.map((person) => <Pressable key={person.id} onPress={() => onOpenProfile(person)} accessibilityRole="button" accessibilityLabel={`Open ${person.displayName}'s profile`} style={styles.followerRow}><Avatar profile={person} size={42} /><View style={styles.followerInfo}><Text numberOfLines={1} style={styles.followerName}>{person.displayName}</Text><Text numberOfLines={1} style={styles.followerHandle}>@{person.handle}</Text></View></Pressable>)}{following.length === 0 ? <EmptyState emoji="🌱" title="You’re not following anyone yet" detail="Find people whose interests feel like yours in Explore." /> : null}</View> : null}
    <View style={styles.walletCard}><View><Text style={styles.walletEyebrow}>YOUR WALLET</Text><Text style={styles.walletAmount}>◉ {walletBalance.toLocaleString()} <Text style={styles.walletCoins}>coins</Text></Text></View><ActionButton compact variant="dark" label="Add coins" onPress={onStore} /></View>
    <View style={styles.sectionPad}><SectionTitle eyebrow="YOUR LITTLE CORNERS" title="Circles you’re in" />{circles.map((circle) => <Pressable key={circle.id} onPress={() => onCircle(circle)} style={styles.profileCircleRow}><View style={[styles.profileCircleIcon, { backgroundColor: circle.color }]}><Text style={{ fontSize: 22 }}>{circle.interest === 'Film' ? '🎞️' : circle.interest === 'Gardening' ? '🌱' : '🎧'}</Text></View><View style={{ flex: 1 }}><Text style={styles.profileCircleName}>{circle.name}</Text><Text style={styles.profileCircleMeta}>{formatCount(circle.members)} members · {circle.interest}</Text></View><Text style={{ color: colors.muted, fontSize: 20 }}>›</Text></Pressable>)}
    {!signedIn && configured ? <View style={styles.authCard}><Text style={styles.authTitle}>Save your place here</Text><Text style={styles.authCopy}>Sign in to sync your circles and meet your people.</Text><TextInput value={authEmail} onChangeText={onEmail} autoCapitalize="none" keyboardType="email-address" placeholder="Email address" placeholderTextColor="#A6A0A0" style={styles.field} /><TextInput value={authPassword} onChangeText={onPassword} secureTextEntry placeholder="Password" placeholderTextColor="#A6A0A0" style={styles.field} />{authError ? <Text style={styles.authError}>{authError}</Text> : null}<View style={styles.authButtons}><ActionButton compact label={authBusy ? 'Please wait…' : 'Create account'} onPress={() => onAuth('signUp')} disabled={authBusy || !authEmail || authPassword.length < 8} /><Pressable onPress={() => onAuth('signIn')}><Text style={styles.signInText}>I have an account</Text></Pressable></View></View> : null}
    {signedIn && configured ? <Pressable style={styles.signOutButton} onPress={onSignOut}><Text style={styles.signOutText}>Sign out</Text></Pressable> : null}
    </View>
  </ScrollView>;
}

export function PublicProfileScreen({ profile, followers, following, posts, isFollowing, isMutual, loading, signedIn, onBack, onFollow, onMessage, onOpenProfile, onLike, onReply }: { profile: Profile; followers: Profile[]; following: Profile[]; posts: CirclePost[]; isFollowing: boolean; isMutual: boolean; loading: boolean; signedIn: boolean; onBack: () => void; onFollow: () => void; onMessage: () => void; onOpenProfile: (profile: Profile) => void; onLike: (id: UUID) => void; onReply: (post: CirclePost) => void }) {
  const peopleList = (title: string, users: Profile[]) => <View style={styles.sectionPad}><SectionTitle eyebrow="COMMUNITY" title={`${title} · ${users.length}${users.length === 100 ? '+' : ''}`} />{users.map((person) => <Pressable key={person.id} onPress={() => onOpenProfile(person)} accessibilityRole="button" accessibilityLabel={`Open ${person.displayName}'s profile`} style={styles.followerRow}><Avatar profile={person} size={42} /><View style={styles.followerInfo}><Text numberOfLines={1} style={styles.followerName}>{person.displayName}</Text><Text numberOfLines={1} style={styles.followerHandle}>@{person.handle}</Text></View><Text style={styles.publicProfileChevron}>›</Text></Pressable>)}{!loading && users.length === 0 ? <Text style={styles.publicProfileEmpty}>No {title.toLowerCase()} yet.</Text> : null}</View>;
  return <ScrollView contentContainerStyle={styles.pageContent} showsVerticalScrollIndicator={false}>
    <View style={styles.publicProfileHeader}><Pressable onPress={onBack} accessibilityRole="button" accessibilityLabel="Back"><Text style={styles.publicProfileBack}>‹</Text></Pressable><Text style={styles.publicProfileHeaderLabel}>MEMBER PROFILE</Text><View style={{ width: 36 }} /></View>
    <View style={styles.profileHero}><Avatar profile={profile} size={88} ring /><Text style={styles.profileName}>{profile.displayName}</Text><Text style={styles.profileHandle}>@{profile.handle}</Text><Text style={styles.profileBio}>{profile.bio || 'Finding new corners of the internet.'}</Text>
      <View style={styles.publicInterests}>{profile.interests.map((interest) => <Pill key={interest} label={interest} selected={false} />)}</View>
      {signedIn ? <View style={styles.publicProfileActions}><ActionButton compact variant={isFollowing ? 'secondary' : 'primary'} label={isFollowing ? 'Following' : 'Follow'} onPress={onFollow} /><ActionButton compact variant="outline" label={isMutual ? 'Message' : 'Follow each other to message'} disabled={!isMutual} onPress={onMessage} /></View> : null}
      <View style={styles.profileStats}><View style={styles.stat}><Text style={styles.statValue}>{posts.length}</Text><Text style={styles.statLabel}>posts</Text></View><View style={styles.statLine} /><View style={styles.stat}><Text style={styles.statValue}>{following.length}{following.length === 100 ? '+' : ''}</Text><Text style={styles.statLabel}>following</Text></View><View style={styles.statLine} /><View style={styles.stat}><Text style={styles.statValue}>{followers.length}{followers.length === 100 ? '+' : ''}</Text><Text style={styles.statLabel}>followers</Text></View></View>
    </View>
    {loading ? <View style={styles.publicProfileLoading}><Text style={styles.publicProfileEmpty}>Loading profile and community…</Text></View> : null}
    {peopleList('Followers', followers)}{peopleList('Following', following)}
    <View style={styles.sectionPad}><SectionTitle eyebrow="IN THEIR CIRCLES" title="Recent posts" />{posts.map((post) => <PostCard key={post.id} post={post} onLike={() => onLike(post.id)} onReply={() => onReply(post)} />)}{posts.length === 0 && !loading ? <EmptyState emoji="🌱" title="No visible posts yet" detail="Posts appear here when you share a circle with this member." /> : null}</View>
  </ScrollView>;
}

export function CircleDetailSheet({ circle, posts, requested, joining, onClose, onJoin, onLeave, onPost, onLike, onCreatePost }: { circle: Circle; posts: CirclePost[]; requested: boolean; joining: boolean; onClose: () => void; onJoin: () => void; onLeave: () => void; onPost: (post: CirclePost) => void; onLike: (id: UUID) => void; onCreatePost: () => void }) {
  return <Sheet onClose={onClose} title={circle.name} eyebrow={`${circle.interest.toUpperCase()} · ${formatCount(circle.members)} MEMBERS`}>
    <Text style={styles.circleDetailDescription}>{circle.description || `A community for people who love ${circle.interest.toLowerCase()}.`}</Text>
    <View style={styles.circleDetailMeta}><Text style={styles.circleDetailPrivacy}>{circle.isPrivate ? '🔒 Private circle' : '🌱 Public circle'}</Text><Text style={styles.circleDetailPrivacy}>{circle.isMember ? 'You’re a member' : requested ? 'Request pending' : 'Find your people here'}</Text></View>
    {!circle.isMember && !requested ? <ActionButton label={joining ? 'Joining…' : circle.isPrivate ? 'Request to join' : 'Join this circle'} disabled={joining} onPress={onJoin} /> : null}
    {requested ? <ActionButton compact variant="secondary" label="Cancel join request" onPress={onLeave} /> : null}
    {circle.isMember ? <><ActionButton compact variant="secondary" label="Write a post in this circle" onPress={onCreatePost} />{circle.isOwner ? <Text style={styles.circleOwnerNote}>You own this circle. Transfer ownership before leaving.</Text> : <Pressable onPress={onLeave} accessibilityRole="button" accessibilityLabel={`Leave ${circle.name}`} style={styles.leaveCircleButton}><Text style={styles.leaveCircleText}>Leave circle</Text></Pressable>}</> : null}
    <View style={{ height: 22 }} /><SectionTitle eyebrow="IN THIS CIRCLE" title="Recent posts" />
    {posts.length ? posts.map((post) => <PostCard key={post.id} post={post} onLike={() => onLike(post.id)} onReply={() => onPost(post)} />) : <EmptyState emoji="🌱" title="The first post is yours" detail={circle.isMember ? 'Start a conversation with this circle.' : 'Join this circle to read and share posts.'} />}
  </Sheet>;
}

export function PostRepliesSheet({ post, comments, draft, onDraft, onSend, onClose }: { post: CirclePost; comments: PostComment[]; draft: string; onDraft: (value: string) => void; onSend: () => Promise<void>; onClose: () => void }) {
  return <Sheet onClose={onClose} title="Replies" eyebrow={`${post.circleName.toUpperCase()} · ${comments.length} REPLIES`}>
    <View style={styles.replyPost}><Text style={styles.replyAuthor}>{post.author.displayName}</Text><Text style={styles.replyBody}>{post.body || 'Shared a moment with the circle.'}</Text></View>
    {comments.length ? comments.map((comment) => <View key={comment.id} style={styles.replyRow}><Avatar profile={comment.author} size={34} /><View style={styles.replyBubble}><Text style={styles.replyAuthor}>{comment.author.displayName} <Text style={styles.replyTime}>· {comment.createdAt}</Text></Text><Text style={styles.replyBody}>{comment.body}</Text></View></View>) : <Text style={styles.noReplies}>No replies yet. Say hello first.</Text>}
    <View style={styles.replyComposer}><TextInput value={draft} onChangeText={onDraft} placeholder="Write a reply…" placeholderTextColor="#A6A0A0" style={styles.replyInput} maxLength={2000} onSubmitEditing={() => void onSend().catch(() => {})} returnKeyType="send" /><ActionButton compact label="Send" disabled={!draft.trim()} onPress={() => void onSend().catch(() => {})} /></View>
  </Sheet>;
}

export function TabBar({ selected, onChange }: { selected: Tab; onChange: (tab: Tab) => void }) {
  const items: { tab: Tab; label: string }[] = [{ tab: 'home', label: 'Home' }, { tab: 'circles', label: 'Explore' }, { tab: 'live', label: 'Live' }, { tab: 'inbox', label: 'Inbox' }, { tab: 'profile', label: 'You' }];
  return <View style={styles.tabBar}>{items.map((item) => <Pressable key={item.tab} accessibilityRole="button" accessibilityLabel={`${item.label} tab`} accessibilityState={{ selected: selected === item.tab }} onPress={() => onChange(item.tab)} style={styles.tabItem}><TabGlyph tab={item.tab} selected={selected === item.tab} /><Text style={[styles.tabLabel, selected === item.tab && styles.tabLabelActive]}>{item.label}</Text></Pressable>)}</View>;
}

export function TabGlyph({ tab, selected }: { tab: Tab; selected: boolean }) {
  const color = selected ? colors.coral : '#918B91';
  if (tab === 'live') return <View style={[styles.navLiveIcon, selected && styles.navLiveIconSelected]}><View style={styles.navLiveSignalOuter}><View style={styles.navLiveSignalInner}><View style={styles.navLiveSignalDot} /></View></View></View>;
  if (tab === 'home') return <View style={styles.navGlyph} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
    <View style={[styles.navHomeRoof, { borderColor: color }]} />
    <View style={[styles.navHomeBody, { borderColor: color }]}><View style={[styles.navHomeDoor, { backgroundColor: color }]} /></View>
  </View>;
  if (tab === 'circles') return <View style={styles.navGlyph} accessibilityElementsHidden importantForAccessibility="no-hide-descendants"><View style={[styles.navCompass, { borderColor: color }]}><View style={[styles.navCompassNeedle, { borderColor: color }]} /></View></View>;
  if (tab === 'inbox') return <View style={styles.navGlyph} accessibilityElementsHidden importantForAccessibility="no-hide-descendants"><View style={[styles.navEnvelope, { borderColor: color }]}><View style={[styles.navEnvelopeLeft, { backgroundColor: color }]} /><View style={[styles.navEnvelopeRight, { backgroundColor: color }]} /></View></View>;
  return <View style={styles.navGlyph} accessibilityElementsHidden importantForAccessibility="no-hide-descendants"><View style={[styles.navPersonHead, { borderColor: color }]} /><View style={[styles.navPersonShoulders, { borderColor: color }]} /></View>;
}

export function CreatePostSheet({ busy, circles, selectedCircleId, onSelectCircle, body, onBody, attachment, onPick, onClearAttachment, onClose, onSubmit }: { busy: boolean; circles: Circle[]; selectedCircleId: string; onSelectCircle: (id: string) => void; body: string; onBody: (text: string) => void; attachment: Attachment | null; onPick: (kind: 'image' | 'gif' | 'video') => void; onClearAttachment: () => void; onClose: () => void; onSubmit: () => void }) {
  return <Sheet onClose={onClose} title="Share a little something" eyebrow="A NOTE FOR YOUR PEOPLE">{circles.length ? <><Text style={styles.sheetLabel}>POST TO</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 13 }}>{circles.map((circle) => <Pill key={circle.id} label={circle.name} selected={selectedCircleId === circle.id} onPress={() => onSelectCircle(circle.id)} />)}</ScrollView></> : <Text style={styles.sheetCopy}>Join a circle before you share a post.</Text>}<TextInput multiline value={body} onChangeText={onBody} editable={!busy} placeholder="What’s on your mind?" placeholderTextColor="#AAA4A1" style={styles.composerInput} textAlignVertical="top" maxLength={5000} />{attachment ? <View style={styles.attachmentPreview}><AttachmentPreviewMedia attachment={attachment} /><View style={{ flex: 1 }}><Text style={styles.attachmentTitle}>{attachment.kind === 'video' ? 'Video attached' : attachment.kind === 'gif' ? 'GIF attached' : 'Photo attached'}</Text><Text style={styles.attachmentMeta}>{attachment.fileName}</Text></View><Pressable disabled={busy} onPress={onClearAttachment} accessibilityRole="button" accessibilityLabel="Remove attachment"><Text style={styles.removeAttachment}>×</Text></Pressable></View> : null}<View style={styles.mediaButtons}><MediaButton icon="▧" label="Photo" disabled={busy} onPress={() => void onPick('image')} /><MediaButton icon="GIF" label="GIF" disabled={busy} onPress={() => void onPick('gif')} /><MediaButton icon="▷" label="Video" disabled={busy} onPress={() => void onPick('video')} /></View><ActionButton label={busy ? 'Sharing…' : 'Share with your circle'} onPress={onSubmit} disabled={busy || !circles.length} /></Sheet>;
}

export function AttachmentPreviewMedia({ attachment }: { attachment: Attachment }) {
  return attachment.kind === 'video' ? <VideoAttachmentPreview uri={attachment.uri} /> : <Image source={{ uri: attachment.uri }} style={styles.attachmentImage} />;
}

export function VideoAttachmentPreview({ uri }: { uri: string }) {
  const player = useVideoPlayer(uri);
  return <VideoView player={player} style={styles.attachmentImage} contentFit="cover" nativeControls={false} />;
}

export function CreateCircleSheet({ busy, name, description, interest, isPrivate, onName, onDescription, onInterest, onPrivate, onClose, onSubmit }: { busy: boolean; name: string; description: string; interest: string; isPrivate: boolean; onName: (value: string) => void; onDescription: (value: string) => void; onInterest: (value: string) => void; onPrivate: (value: boolean) => void; onClose: () => void; onSubmit: () => void }) {
  return <Sheet onClose={onClose} title="Make a little space." eyebrow="START A NEW CIRCLE"><TextInput value={name} onChangeText={onName} editable={!busy} placeholder="Circle name" placeholderTextColor="#AAA4A1" style={styles.field} maxLength={48} /><TextInput value={interest} onChangeText={onInterest} editable={!busy} placeholder="Interest, like film or gardening" placeholderTextColor="#AAA4A1" style={styles.field} /><TextInput value={description} onChangeText={onDescription} editable={!busy} placeholder="What brings your people together?" placeholderTextColor="#AAA4A1" style={[styles.field, { minHeight: 82 }]} multiline textAlignVertical="top" /><Pressable disabled={busy} accessibilityRole="switch" accessibilityState={{ checked: isPrivate, disabled: busy }} accessibilityLabel="Private circle" onPress={() => onPrivate(!isPrivate)} style={styles.privacyRow}><View style={[styles.toggle, isPrivate && styles.toggleOn]}><View style={[styles.toggleKnob, isPrivate && styles.toggleKnobOn]} /></View><View style={{ flex: 1 }}><Text style={styles.privacyTitle}>{isPrivate ? 'Private circle' : 'Public circle'}</Text><Text style={styles.privacyCopy}>{isPrivate ? 'People ask to join. You decide who gets in.' : 'Anyone can find and join this circle.'}</Text></View><Text style={{ fontSize: 22 }}>{isPrivate ? '🔒' : '🌱'}</Text></Pressable><ActionButton label={busy ? 'Creating…' : 'Create your circle'} onPress={onSubmit} disabled={busy} /></Sheet>;
}

export function StartLiveSheet({ title, onTitle, onClose, onSubmit }: { title: string; onTitle: (text: string) => void; onClose: () => void; onSubmit: () => void }) {
  return <Sheet onClose={onClose} title="Go live, say hello." eyebrow="YOUR ROOM, YOUR PEOPLE"><Text style={styles.sheetCopy}>Set the tone for your room. You can invite up to three co-hosts once you’re live.</Text><TextInput value={title} onChangeText={onTitle} placeholder="What are we hanging out for?" placeholderTextColor="#AAA4A1" style={styles.field} maxLength={120} /><View style={styles.stagePreview}><View style={styles.stageAvatar}><Text style={{ fontSize: 27 }}>◉</Text></View><View><Text style={styles.stageTitle}>A stage for four</Text><Text style={styles.stageCopy}>You + up to three co-hosts</Text></View></View><ActionButton label="Start livestream" onPress={onSubmit} /></Sheet>;
}

export function Sheet({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) {
  return <Modal transparent animationType="slide" onRequestClose={onClose}><KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.modalShade}><Pressable style={StyleSheet.absoluteFill} onPress={onClose} /><View style={styles.sheetPanel}><View style={styles.grabber} /><View style={styles.sheetHeader}><View style={{ flex: 1 }}><Text style={styles.sheetEyebrow}>{eyebrow}</Text><Text style={styles.sheetTitle}>{title}</Text></View><Pressable onPress={onClose} style={styles.closeButton}><Text style={styles.closeButtonText}>×</Text></Pressable></View><ScrollView keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>{children}<View style={{ height: 24 }} /></ScrollView></View></KeyboardAvoidingView></Modal>;
}

export function MediaButton({ icon, label, onPress, disabled }: { icon: string; label: string; onPress: () => void; disabled?: boolean }) { return <Pressable onPress={onPress} disabled={disabled} accessibilityRole="button" accessibilityLabel={`Add ${label.toLowerCase()}`} accessibilityState={{ disabled: Boolean(disabled) }} style={[styles.mediaButton, disabled && { opacity: 0.45 }]}><Text style={styles.mediaIcon}>{icon}</Text><Text style={styles.mediaLabel}>{label}</Text></Pressable>; }

export function LiveRoom({ session, profile, walletBalance, gifts, giftEvents, selectedGift, giftSending, liveRequestStatus, liveRequests, signedIn, backendReady: configured, streamCredentials, streamError, remoteUids, micEnabled, cameraEnabled, onClose, onGiftSelect, onGiftSend, onBuyCoins, onRequestCoHost, onDecision, onReport, onToggleMic, onToggleCamera, onSwitchCamera }: { session: LiveSession; profile: Profile; walletBalance: number; gifts: Gift[]; giftEvents: LiveGiftEvent[]; selectedGift: Gift | null; giftSending: boolean; liveRequestStatus: 'none' | 'pending' | 'accepted' | 'declined'; liveRequests: { id: UUID; requester: Profile }[]; signedIn: boolean; backendReady: boolean; streamCredentials: { uid: number; role: string } | null; streamError: string; remoteUids: number[]; micEnabled: boolean; cameraEnabled: boolean; onClose: () => void; onGiftSelect: (gift: Gift | null) => void; onGiftSend: (gift: Gift) => void; onBuyCoins: () => void; onRequestCoHost: () => void; onDecision: (id: UUID, user: Profile, accepted: boolean) => void; onReport: () => void; onToggleMic: () => void; onToggleCamera: () => void; onSwitchCamera: () => void }) {
  const host = session.host.id === profile.id;
  const onStage = host || session.seats.some((seat) => seat.user.id === profile.id && seat.role === 'cohost');
  const canRequest = !onStage && liveRequestStatus === 'none' && session.seats.length < 4;
  const [giftSearch, setGiftSearch] = useState('');
  const displayGifts = gifts.filter((gift) => gift.name.toLowerCase().includes(giftSearch.toLowerCase())).slice(0, 300);
  return <View style={styles.roomScreen}>
    <ImageBackground source={{ uri: 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=1200&h=900&fit=crop' }} style={styles.roomBackdrop}>
      <View style={styles.roomTint} />
      {streamCredentials && streamCredentials.role !== 'viewer' ? <AgoraVideoTile uid={streamCredentials.uid} local style={StyleSheet.absoluteFill} /> : null}
      <SafeAreaView style={styles.roomSafe} edges={['top', 'bottom']}>
        <View style={styles.roomHeader}><Pressable onPress={onClose} style={styles.roomBack} accessibilityRole="button" accessibilityLabel="Leave live room"><Text style={styles.roomBackText}>⌄</Text></Pressable><View style={styles.roomHeaderCenter}><View style={styles.roomLivePill}><View style={styles.liveDot} /><Text style={styles.roomLiveText}>LIVE</Text></View><Text style={styles.roomViewerText}>◉ {formatCount(session.viewerCount)} watching</Text></View><Pressable onPress={onReport} style={styles.roomMore} accessibilityRole="button" accessibilityLabel="Report live room"><Text style={styles.roomMoreText}>···</Text></Pressable></View>
        <View style={styles.roomTitleBlock}><Text style={styles.roomCircle}>{session.circleName ?? 'AROUND CIRCLES'}</Text><Text numberOfLines={2} style={styles.roomTitle}>{session.title}</Text></View>
        <View style={styles.stageArea}><View style={styles.stageGlow} />{session.seats.slice(0, 4).map((seat, index) => { const localVideo = seat.user.id === profile.id && streamCredentials && streamCredentials.role !== 'viewer'; const remoteUid = agoraUidFor(seat.user.id); const remoteVideo = streamCredentials && remoteUids.includes(remoteUid); return <View key={seat.user.id} style={[styles.stagePerson, index > 1 && styles.stagePersonSmall]}>{localVideo ? <AgoraVideoTile uid={streamCredentials.uid} local style={styles.stageAvatarImage} /> : remoteVideo ? <AgoraVideoTile uid={remoteUid} style={styles.stageAvatarImage} /> : <Avatar profile={seat.user} size={index > 1 ? 58 : 78} ring />}<View style={styles.speakingHalo} /><Text style={styles.stagePersonName}>{seat.user.id === profile.id ? 'You' : seat.user.displayName.split(' ')[0]}</Text><Text style={styles.stageRole}>{seat.role === 'host' ? 'HOST' : 'CO-HOST'}</Text></View>; })}{Array.from({ length: Math.max(0, 4 - session.seats.length) }).slice(0, 2).map((_, index) => <View key={`empty-${index}`} style={[styles.emptySeat, index > 0 && styles.emptySeatSmall]}><Text style={styles.emptySeatIcon}>＋</Text><Text style={styles.emptySeatText}>{host ? 'ROOM FOR A FRIEND' : 'OPEN SEAT'}</Text></View>)}</View>
        {liveRequests.length && host ? <View style={styles.requestCard}><View style={{ flex: 1 }}><Text style={styles.requestTitle}>{liveRequests.length} co-host request{liveRequests.length > 1 ? 's' : ''}</Text><Text style={styles.requestCopy}>{liveRequests[0].requester.displayName} would like to join</Text></View><Pressable onPress={() => onDecision(liveRequests[0].id, liveRequests[0].requester, false)} style={styles.requestDecline}><Text style={styles.requestDeclineText}>×</Text></Pressable><Pressable onPress={() => onDecision(liveRequests[0].id, liveRequests[0].requester, true)} style={styles.requestAccept}><Text style={styles.requestAcceptText}>Let in</Text></Pressable></View> : null}
        {!host && liveRequestStatus !== 'none' ? <View style={styles.requestStatus}><Text style={styles.requestStatusText}>{liveRequestStatus === 'pending' ? 'Request sent · the host will let you know' : liveRequestStatus === 'accepted' ? 'You’re on stage · reconnecting as a co-host' : 'The host passed this time'}</Text></View> : null}
        <View style={styles.roomLower}>{giftEvents.slice(0, 2).map((event) => <View key={event.id} style={styles.liveGiftEvent}><Text style={styles.liveGiftEmoji}>{event.emoji}</Text><Text style={styles.liveGiftCopy}><Text style={{ fontWeight: '900' }}>{event.sender.displayName}</Text> sent {event.giftName}</Text><Text style={styles.liveGiftValue}>◉ {event.coins}</Text></View>)}
          <View style={styles.roomControls}>{onStage ? <><Pressable onPress={onToggleMic} style={styles.roomControl} accessibilityRole="button" accessibilityLabel={micEnabled ? "Mute microphone" : "Unmute microphone"}><Text style={styles.roomControlIcon}>{micEnabled ? '🎙' : '🔇'}</Text></Pressable><Pressable onPress={onToggleCamera} style={styles.roomControl} accessibilityRole="button" accessibilityLabel={cameraEnabled ? "Turn camera off" : "Turn camera on"}><Text style={styles.roomControlIcon}>{cameraEnabled ? '◉' : '⊘'}</Text></Pressable><Pressable onPress={onSwitchCamera} style={styles.roomControl} accessibilityRole="button" accessibilityLabel="Switch camera"><Text style={styles.roomControlIcon}>↻</Text></Pressable></> : canRequest ? <Pressable onPress={onRequestCoHost} style={styles.requestSeat}><Text style={styles.requestSeatText}>＋ Ask to join</Text></Pressable> : null}<View style={styles.roomControlHint}><Text style={styles.roomControlHintText}>Appreciate the host</Text></View><Pressable onPress={() => onGiftSelect(selectedGift ? null : gifts[0] ?? null)} style={styles.giftOpen} accessibilityRole="button" accessibilityLabel="Open gift catalog"><Text style={styles.giftOpenText}>🎁</Text></Pressable></View>
        </View>
        {streamError ? <View style={styles.streamStatus}><Text style={styles.streamStatusText}>{streamError}</Text></View> : configured && !streamCredentials ? <View style={styles.streamStatus}><Text style={styles.streamStatusText}>Connecting to live video…</Text></View> : !configured ? <View style={styles.demoStatus}><Text style={styles.demoStatusText}>Circles live · demo room</Text></View> : null}
      </SafeAreaView>
    </ImageBackground>
    {selectedGift ? <View style={styles.giftDrawer}><View style={styles.giftDrawerHeader}><View><Text style={styles.giftDrawerEyebrow}>A LITTLE LOVE</Text><Text style={styles.giftDrawerTitle}>Send a gift</Text></View><View style={styles.coinBalance}><Text style={styles.coinBalanceText}>◉ {walletBalance.toLocaleString()}</Text><Pressable onPress={onBuyCoins} disabled={giftSending}><Text style={styles.addCoinText}>＋</Text></Pressable></View><Pressable onPress={() => onGiftSelect(null)} disabled={giftSending} accessibilityRole="button" accessibilityLabel="Close gift catalog"><Text style={styles.giftClose}>×</Text></Pressable></View><TextInput value={giftSearch} onChangeText={setGiftSearch} placeholder="Find a gift" placeholderTextColor="#A6A0A0" style={styles.giftSearch} /><ScrollView style={styles.giftScroll} contentContainerStyle={styles.giftGrid}>{displayGifts.map((gift) => <Pressable key={gift.id} disabled={giftSending} onPress={() => onGiftSelect(gift)} style={[styles.giftTile, selectedGift.id === gift.id && styles.giftTileSelected, giftSending && { opacity: 0.55 }]}><Text style={styles.giftEmoji}>{gift.emoji}</Text><Text numberOfLines={1} style={styles.giftName}>{gift.name}</Text><Text style={styles.giftPrice}>◉ {gift.coins.toLocaleString()}</Text></Pressable>)}</ScrollView><View style={styles.giftDrawerFooter}><Text style={styles.giftSelectedText}>{selectedGift.emoji} {selectedGift.name} · {selectedGift.coins} coins</Text><ActionButton compact label={giftSending ? 'Sending…' : 'Send'} onPress={() => onGiftSend(selectedGift)} disabled={giftSending || walletBalance < selectedGift.coins} /></View><Pressable onPress={() => onBuyCoins()} disabled={giftSending}><Text style={styles.walletLink}>Need coins? Open wallet</Text></Pressable></View> : null}
  </View>;
}

export function ChatScreen({ conversation, profile, hasOlder, onLoadOlder, onClose, onSend, onReport }: { conversation: Conversation; profile: Profile; hasOlder: boolean; onLoadOlder: (before: string) => Promise<DirectMessage[]>; onClose: () => void; onSend: (body: string) => Promise<void>; onReport: () => void }) {
  const [draft, setDraft] = useState('');
  const [sending, setSending] = useState(false);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const sendingRef = useRef(false);
  const messagesRef = useRef<ScrollView>(null);
  const messageScrollOffset = useRef(0);
  const messageContentHeight = useRef(0);
  const preserveOlderPosition = useRef(false);
  const send = async () => {
    const trimmed = draft.trim();
    if (!trimmed || sendingRef.current) return;
    sendingRef.current = true;
    setSending(true);
    try { await onSend(trimmed); setDraft(''); }
    catch { /* The parent reports send errors; keep the draft so it can be retried. */ }
    finally { sendingRef.current = false; setSending(false); }
  };
  const firstMessageTimestamp = conversation.messages.find((message) => message.createdAtIso)?.createdAtIso;
  return <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.chatScreen}><View style={styles.chatHeader}><Pressable onPress={onClose} accessibilityRole="button" accessibilityLabel="Close conversation"><Text style={styles.backArrow}>‹</Text></Pressable><Avatar profile={conversation.peer} size={38} /><View style={{ flex: 1 }}><Text style={styles.chatName}>{conversation.peer.displayName}</Text><Text style={styles.chatStatus}>Following each other</Text></View><Pressable onPress={onReport} accessibilityRole="button" accessibilityLabel="Conversation options"><Text style={styles.moreIcon}>···</Text></Pressable></View><View style={styles.chatIntro}><Avatar profile={conversation.peer} size={70} /><Text style={styles.chatIntroName}>{conversation.peer.displayName}</Text><Text style={styles.chatIntroHandle}>@{conversation.peer.handle}</Text><Text style={styles.chatIntroNote}>You’re both part of the same little corner.</Text></View>{hasOlder && firstMessageTimestamp ? <Pressable disabled={loadingOlder} accessibilityRole="button" accessibilityLabel="Load earlier messages" onPress={() => { setLoadingOlder(true); preserveOlderPosition.current = true; void onLoadOlder(firstMessageTimestamp).then((loaded) => { if (!loaded.length) preserveOlderPosition.current = false; }).catch(() => { preserveOlderPosition.current = false; }).finally(() => setLoadingOlder(false)); }}><Text style={styles.signInText}>{loadingOlder ? 'Loading earlier messages…' : 'Load earlier messages'}</Text></Pressable> : null}<ScrollView ref={messagesRef} contentContainerStyle={styles.chatMessages} keyboardShouldPersistTaps="handled" onScroll={(event) => { messageScrollOffset.current = event.nativeEvent.contentOffset.y; }} scrollEventThrottle={16} onContentSizeChange={(_, height) => { const delta = height - messageContentHeight.current; messageContentHeight.current = height; if (preserveOlderPosition.current) { preserveOlderPosition.current = false; messagesRef.current?.scrollTo({ y: Math.max(0, messageScrollOffset.current + delta), animated: false }); } else messagesRef.current?.scrollToEnd({ animated: true }); }}>{conversation.messages.map((message) => { const mine = message.senderId === profile.id; return <View key={message.id} style={[styles.messageBubble, mine ? styles.messageMine : styles.messageTheirs]}><Text style={[styles.messageText, mine && { color: '#FFFFFF' }]}>{message.body}</Text><Text style={[styles.messageTime, mine && { color: 'rgba(255,255,255,0.68)' }]}>{message.createdAt}</Text></View>; })}</ScrollView><View style={styles.messageComposer}><TextInput value={draft} onChangeText={setDraft} editable={!sending} maxLength={4000} placeholder="Write a message…" placeholderTextColor="#A6A0A0" style={styles.messageInput} onSubmitEditing={() => void send()} returnKeyType="send" accessibilityLabel="Message" /><Pressable onPress={() => void send()} disabled={sending || !draft.trim()} style={[styles.messageSend, (sending || !draft.trim()) && { opacity: 0.55 }]} accessibilityRole="button" accessibilityLabel={sending ? 'Sending message' : 'Send message'}><Text style={styles.messageSendText}>{sending ? '…' : '↑'}</Text></Pressable></View></KeyboardAvoidingView>;
}
